<script lang="ts">
 import {onMount} from 'svelte';
 import {get,post,API_BASE} from '$lib/api';
 type Clip={id:string;asset_id:string;start:number;trim:number;duration:number;speed:number;[key:string]:any};
 type Cue={id:string;utterance_id:string;start:number;end:number;text:string;source_clip_id?:string;character_id?:string;language?:string};
 type Draft={version:number;width:number;height:number;fps:number;duration:number;caption_style:string;clips:Clip[];audio:Clip[];captions:Cue[];[key:string]:any};
 let draft:Draft={version:1,width:640,height:360,fps:24,duration:2,caption_style:'default',clips:[],audio:[],captions:[]};
 let assets:any[]=[];let runtime:any=null;let error='';let log='';let busy=false;let revision='';let rendered='';let snapshots:string[]=[];
 let instruction='';let selectedClip='';let selectedAudio='';let advanced='';let advancedDirty=false;let notice='';
 const uid=(prefix:string)=>prefix+'-'+crypto.randomUUID();
 const assetName=(id:string)=>assets.find(a=>a.id===id)?.name??id;
 function invalidate(){revision='';rendered='';snapshots=[];log='';notice='Unsaved changes — save before checking or rendering.';if(typeof window!=='undefined'){const url=new URL(window.location.href);url.searchParams.delete('revision');window.history.replaceState({},'',url)}}
 onMount(async()=>{try{[assets,runtime]=await Promise.all([get('/compositions/sources'),get('/compositions/runtime')]);const saved=new URL(window.location.href).searchParams.get('revision');if(saved){draft=await get('/compositions/'+encodeURIComponent(saved));revision=draft.revision;notice='Saved edit loaded.';}}catch(e){error=String(e)}});
 function add(track:'clips'|'audio',id:string){if(!id)return;draft[track]=[...draft[track],{id:uid(track==='audio'?'audio':'clip'),asset_id:id,start:0,trim:0,duration:draft.duration,speed:1}];invalidate()}
 function remove(track:'clips'|'audio',index:number){if(track==='clips')removeLinkedCaptions(draft.clips[index].id);draft[track]=draft[track].filter((_,i)=>i!==index);invalidate()}
 function move(index:number,direction:number){const clips=[...draft.clips];[clips[index],clips[index+direction]]=[clips[index+direction],clips[index]];draft.clips=clips;invalidate()}
 function dimensions(value:string){[draft.width,draft.height]=value.split('x').map(Number);invalidate()}
 function addCaption(){draft.captions=[...draft.captions,{id:uid('cue'),utterance_id:'',start:0,end:Math.min(2,draft.duration),text:''}];invalidate()}
 function applyAdvanced(){try{const parsed=JSON.parse(advanced);if(!parsed||!Array.isArray(parsed.clips)||!Array.isArray(parsed.audio)||!Array.isArray(parsed.captions))throw Error('Include clips, audio and captions arrays.');draft=parsed;advancedDirty=false;error='';invalidate()}catch(e){error='Cannot apply advanced changes: '+String(e)}}
 function removeLinkedCaptions(clipID:string){draft.captions=draft.captions.filter(c=>c.source_clip_id!==clipID);draft.caption_bindings=(draft.caption_bindings??[]).filter((b:any)=>b.clip_id!==clipID);invalidate()}
 async function importCaptions(clip:Clip){busy=true;error='';try{const result=await post('/compositions/captions/import',{clip});draft.captions=[...draft.captions.filter(c=>c.source_clip_id!==clip.id),...result.captions];draft.caption_bindings=[...(draft.caption_bindings??[]).filter((b:any)=>b.clip_id!==clip.id),result.binding];invalidate();notice='Approved captions reused. They stay linked to the script, final audio and this clip timing.';}catch(e){error=String(e)}finally{busy=false}}
 async function plan(){busy=true;error='';try{const result=await post('/director/composition-plan',{instruction,manifest:draft});if(!result.manifest||!Array.isArray(result.manifest.clips)||!Array.isArray(result.manifest.audio)||!Array.isArray(result.manifest.captions))throw Error('The local session returned an incomplete edit.');draft=result.manifest;invalidate();advancedDirty=false;notice='Plan ready for review. Check the layers and timings, then save when ready.';}catch(e){error=String(e)}finally{busy=false}}
 async function save(){busy=true;error='';try{draft=await post('/compositions',draft);revision=draft.revision;rendered='';notice='Edit saved. Preview or render when ready.';const url=new URL(window.location.href);url.searchParams.set('revision',revision);window.history.replaceState({},'',url);}catch(e){error=String(e)}finally{busy=false}}
 async function run(operation:string){busy=true;error='';try{const result=await post(`/compositions/${revision}/run`,{operation,revision});log=result.log;if(result.asset_url)rendered=API_BASE+result.asset_url;if(result.snapshots)snapshots=result.snapshots.map((p:string)=>API_BASE+p);notice=operation==='render'?'Rendered video added to your project assets.':'Review complete.';}catch(e){error=String(e)}finally{busy=false}}
</script>
<svelte:head><title>Compositions · VideoFlow</title></svelte:head>
<main>
 <a href="/render">← Back to renders</a><header><div><h1>Edit a composition</h1><p>Combine existing clips, sound and approved captions. Your original media stays intact.</p></div><span class="runtime">{runtime?.ready?'Local renderer ready':'Local renderer needs setup'}</span></header>
 {#if error}<p class="error" role="alert">{error}</p>{/if}
 <fieldset disabled={busy}>
 <section class="planner"><h2>Describe your edit</h2><label for="instruction">What would you like to change?</label><textarea id="instruction" rows="2" bind:value={instruction} placeholder="Put the opening clip first, add the selected narration, and hold the final shot for two seconds."></textarea><div class="row"><button class="primary" disabled={!instruction.trim()||advancedDirty} onclick={plan}>Plan with local session</button><p>The plan appears below for review. Saving and rendering stay in your control.</p></div></section>
 <section><h2>Canvas</h2><div class="settings"><label>Format<select aria-label="Canvas format" value={`${draft.width}x${draft.height}`} onchange={e=>dimensions(e.currentTarget.value)}><option value="640x360">Landscape · 640 × 360</option><option value="1920x1080">Landscape · 1920 × 1080</option><option value="1080x1920">Portrait · 1080 × 1920</option><option value="1080x1080">Square · 1080 × 1080</option>{#if !['640x360','1920x1080','1080x1920','1080x1080'].includes(`${draft.width}x${draft.height}`)}<option value={`${draft.width}x${draft.height}`}>Custom · {draft.width} × {draft.height}</option>{/if}</select></label><label>Total length (seconds)<input aria-label="Total length" type="number" min="0.1" max="600" step="0.1" bind:value={draft.duration} oninput={invalidate} /></label><label>Frame rate<select bind:value={draft.fps} onchange={invalidate}><option value={24}>24 fps</option><option value={30}>30 fps</option><option value={60}>60 fps</option></select></label></div></section>
 <section><div class="section-head"><h2>Video & image layers</h2><span>Layers play at normal speed. Start times control playback order.</span></div>
 <div class="add-row"><label for="clip-source">Existing asset or rendered clip</label><select id="clip-source" bind:value={selectedClip}><option value="">Choose project media…</option>{#each assets as asset}<option value={asset.id}>{asset.name}</option>{/each}</select><button disabled={!selectedClip} onclick={()=>add('clips',selectedClip)}>Add visual layer</button></div>
 {#if !draft.clips.length}<p class="empty">Add a clip or image to begin, or describe an edit above.</p>{/if}
 {#each draft.clips as clip,i (clip.id)}<div class="media-row"><div class="media-title"><strong>{assetName(clip.asset_id)}</strong><div><button aria-label={`Move visual layer ${i+1} up`} disabled={i===0} onclick={()=>move(i,-1)}>↑</button><button aria-label={`Move visual layer ${i+1} down`} disabled={i===draft.clips.length-1} onclick={()=>move(i,1)}>↓</button><button aria-label={`Remove visual layer ${i+1}`} onclick={()=>remove('clips',i)}>Remove</button></div></div><div class="timing"><label>Start (s)<input aria-label={`Visual layer ${i+1} start`} type="number" min="0" step="0.1" bind:value={clip.start} oninput={invalidate} /></label><label>Trim from source (s)<input aria-label={`Visual layer ${i+1} trim`} type="number" min="0" step="0.1" bind:value={clip.trim} oninput={invalidate} /></label><label>Play length (s)<input aria-label={`Visual layer ${i+1} length`} type="number" min="0.1" step="0.1" bind:value={clip.duration} oninput={invalidate} /></label></div>{#if clip.asset_id.startsWith('output-')}<div class="caption-import"><button onclick={()=>importCaptions(clip)}>Reuse approved captions</button>{#if draft.caption_bindings?.some((b:any)=>b.clip_id===clip.id)}<button onclick={()=>removeLinkedCaptions(clip.id)}>Remove linked captions</button><a href={`/editor/${clip.asset_id.slice(7)}`}>Edit captions at source</a>{/if}</div>{/if}<div class="timeline" aria-hidden="true"><span style={`margin-left:${Math.max(0,Math.min(100,clip.start/draft.duration*100))}%;width:${Math.max(0,Math.min(100-clip.start/draft.duration*100,clip.duration/draft.duration*100))}%`}></span></div></div>{/each}</section>
 <section><h2>Audio tracks</h2><div class="add-row"><label for="audio-source">Existing audio or video sound</label><select id="audio-source" bind:value={selectedAudio}><option value="">Choose project media…</option>{#each assets as asset}<option value={asset.id}>{asset.name}</option>{/each}</select><button disabled={!selectedAudio} onclick={()=>add('audio',selectedAudio)}>Add audio track</button></div>{#if !draft.audio.length}<p class="empty">Keep clip audio, or add separate narration, dialogue or music.</p>{/if}
 {#each draft.audio as clip,i (clip.id)}<div class="media-row"><div class="media-title"><strong>{assetName(clip.asset_id)}</strong><button aria-label={`Remove audio track ${i+1}`} onclick={()=>remove('audio',i)}>Remove</button></div><div class="timing"><label>Start (s)<input aria-label={`Audio track ${i+1} start`} type="number" min="0" step="0.1" bind:value={clip.start} oninput={invalidate} /></label><label>Trim from source (s)<input aria-label={`Audio track ${i+1} trim`} type="number" min="0" step="0.1" bind:value={clip.trim} oninput={invalidate} /></label><label>Play length (s)<input aria-label={`Audio track ${i+1} length`} type="number" min="0.1" step="0.1" bind:value={clip.duration} oninput={invalidate} /></label></div></div>{/each}</section>
 <section><div class="section-head"><h2>Captions</h2><button onclick={addCaption}>Add caption cue</button></div><p>Use exact approved spoken wording and timings from the final audio. Untimed script lines belong in your script draft.</p><label class="style-select">Caption size<select bind:value={draft.caption_style} onchange={invalidate}><option value="default">Standard</option><option value="compact">Small</option><option value="large">Large</option></select></label>
 {#each draft.captions as cue,i (cue.id)}<div class="media-row">{#if cue.source_clip_id}<p class="linked">Linked approved captions · {cue.language??''} · line {cue.utterance_id}. Edit wording at the source; reimport after clip timing changes.</p>{/if}<label>Approved spoken wording<textarea aria-label={`Caption ${i+1} wording`} readonly={!!cue.source_clip_id} rows="2" bind:value={cue.text} oninput={invalidate}></textarea></label><div class="timing"><label>Approved line ID<input aria-label={`Caption ${i+1} approved line ID`} readonly={!!cue.source_clip_id} bind:value={cue.utterance_id} placeholder="e.g. dialogue-1" oninput={invalidate} /></label><label>Starts (s)<input aria-label={`Caption ${i+1} start`} readonly={!!cue.source_clip_id} type="number" min="0" step="0.01" bind:value={cue.start} oninput={invalidate} /></label><label>Ends (s)<input aria-label={`Caption ${i+1} end`} readonly={!!cue.source_clip_id} type="number" min="0.01" step="0.01" bind:value={cue.end} oninput={invalidate} /></label></div><button disabled={!!cue.source_clip_id} aria-label={`Remove caption ${i+1}`} onclick={()=>{draft.captions=draft.captions.filter((_,j)=>j!==i);invalidate()}}>Remove caption</button></div>{/each}</section>
 <details ontoggle={e=>{if(e.currentTarget.open&&!advancedDirty)advanced=JSON.stringify(draft,null,2)}}><summary>Advanced editing data</summary><p>Fine-tune the editable source. Apply changes to review them in the form before saving.</p><label for="advanced">Composition JSON</label><textarea id="advanced" class="json" rows="12" bind:value={advanced} oninput={()=>{advancedDirty=true;invalidate()}} spellcheck="false"></textarea><button disabled={!advancedDirty} onclick={applyAdvanced}>Apply advanced changes</button></details>
 <section class="review"><h2>Review & export</h2><div class="actions"><button class="primary" disabled={advancedDirty} onclick={save}>Save edit</button>{#each [{id:'lint',name:'Check structure'},{id:'check',name:'Check playback'},{id:'snapshot',name:'Preview frames'},{id:'render',name:'Render and add to assets'}] as operation}<button disabled={!revision||!runtime?.ready||advancedDirty} onclick={()=>run(operation.id)}>{operation.name}</button>{/each}</div><p role="status">{busy?'Working locally…':notice||'Save your edit before previewing or rendering.'}</p>{#if !runtime?.ready}<details><summary>Local renderer setup</summary><p>{runtime?.message??'Checking runtime availability…'}</p></details>{/if}</section>
 </fieldset>
 {#if snapshots.length}<section><h2>Preview frames</h2><div class="snapshots">{#each snapshots as snapshot}<img src={snapshot} alt="Composition review snapshot" />{/each}</div></section>{/if}
 {#if rendered}<section><h2>Your rendered video</h2><video controls src={rendered}><track kind="captions" /></video><a href={rendered} download>Download video</a></section>{/if}
 {#if log}<details><summary>Operation details</summary><pre>{log}</pre></details>{/if}
</main>
<style>
 main{max-width:1100px;margin:auto;padding:32px;color:var(--foreground)}header{display:flex;justify-content:space-between;gap:24px;align-items:center;margin:20px 0 32px}h1{font-size:2rem;font-weight:600;letter-spacing:-.025em}h2{font-size:1.2rem;font-weight:600}p{line-height:1.6;color:var(--muted-foreground);margin:10px 0;max-width:72ch}fieldset{border:0;min-width:0;padding:0}section{padding:24px 0;border-top:1px solid var(--border)}section.planner{padding:24px;background:var(--muted);border:0;border-radius:10px;margin-bottom:12px}.runtime{font-size:12px;border:1px solid var(--border);padding:8px 12px;border-radius:6px;white-space:nowrap}.settings,.timing{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-top:16px}label{display:flex;flex-direction:column;gap:7px;font-size:13px;font-weight:500}input,select,textarea{padding:10px 12px;border:1px solid var(--border);border-radius:6px;background:var(--background);color:var(--foreground);min-width:0;font:inherit;font-variant-numeric:tabular-nums;caret-color:var(--foreground)}textarea{width:100%;resize:vertical}button{padding:9px 14px;border:1px solid var(--border);border-radius:6px;background:var(--secondary);color:var(--foreground);font-size:13px;cursor:pointer;white-space:nowrap}button:hover:not(:disabled){background:var(--accent)}button:disabled{opacity:.45;cursor:default}.primary{background:var(--primary);color:var(--primary-foreground);border-color:var(--primary)}.primary:hover:not(:disabled){opacity:.9;background:var(--primary)}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible{outline:2px solid var(--ring);outline-offset:3px}.row,.section-head,.media-title{display:flex;justify-content:space-between;gap:16px;align-items:center}.row{justify-content:flex-start;margin-top:12px}.row p,.section-head span{font-size:12px;color:var(--muted-foreground)}.add-row{display:grid;grid-template-columns:minmax(160px,1fr) minmax(180px,2fr) auto;gap:12px;align-items:center;margin-top:18px}.empty{padding:22px 0;font-size:14px}.media-row{padding:20px 0;border-bottom:1px solid var(--border)}.media-title strong{font-size:14px;overflow-wrap:anywhere}.media-title>div{display:flex;gap:6px}.caption-import{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin-top:16px;font-size:13px}.linked{font-size:12px}.timeline{height:5px;background:var(--muted);margin-top:18px;overflow:hidden;border-radius:3px}.timeline span{display:block;height:100%;background:var(--primary)}.style-select{max-width:180px;margin:16px 0}.actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:18px}.error{color:var(--destructive);border:1px solid var(--destructive);padding:16px;border-radius:6px}.json{font:13px monospace;margin:12px 0}details{padding:16px 0}summary{cursor:pointer;font-size:13px;font-weight:500}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--muted);padding:16px;font:12px monospace}video{display:block;max-width:100%;margin:16px 0}.snapshots{display:flex;gap:12px;flex-wrap:wrap;margin-top:16px}.snapshots img{width:calc(33.333% - 8px);object-fit:contain}a{text-underline-offset:3px}::selection{background:var(--primary);color:var(--primary-foreground)}@media(max-width:700px){main{padding:20px}header{display:block}.runtime{display:inline-block;margin-top:12px}.settings,.timing{grid-template-columns:1fr}.add-row{grid-template-columns:1fr}.section-head,.row{align-items:flex-start;flex-direction:column}.media-title{align-items:flex-start}.media-title>div{flex-wrap:wrap;justify-content:flex-end}.snapshots img{width:100%}.planner{padding:18px!important}}
</style>
